import { describe, expect, it } from 'vitest';
import { readFileSync } from 'node:fs';
import { dirname, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';
import { goldenRows, type GoldenRow } from './flagOffGoldenLib';

/**
 * Flag off = byte-identical. fixtures/bounded-exact-flag-off.golden.json holds a hash of every result of a fixed slice of the recorded corpus (forced decisions, cheap locked
 * yards, exact-enumeration decisions, ladder decisions at tier 1), generated by devtools/generateFlagOffGolden.ts on origin/main at de8d68c4, the commit BEFORE the bounded
 * exact path existed. Reproducing the hashes here shows that without the `boundedExact` option the branch computes what main computed (the contract version string and the
 * position hash derived from it are normalized, because the version bump changes them by design).
 *
 * If a LATER change deliberately alters what the review computes (a budget, a rule, a label), this fails on purpose: regenerate the golden with
 * `npx tsx packages/review-engine/src/devtools/generateFlagOffGolden.ts > packages/review-engine/fixtures/bounded-exact-flag-off.golden.json` and say why in the PR.
 */
const root = resolve(dirname(fileURLToPath(import.meta.url)), '../..');
const golden = JSON.parse(readFileSync(resolve(root, 'fixtures/bounded-exact-flag-off.golden.json'), 'utf8')) as GoldenRow[];
const dir = resolve(root, 'fixtures/recorded-self-play');

describe('bounded exact path: flag off is byte-identical to main', () => {
  it('the golden covers every kind of path', () => {
    expect(new Set(golden.map((row) => row.kind))).toEqual(new Set(['forced', 'locked', 'exact', 'ladder']));
    expect(golden.length).toBeGreaterThanOrEqual(50);
  });

  it('no option: every evaluation of the slice hashes to main\'s', { timeout: 300_000 }, () => {
    expect(goldenRows(dir)).toEqual(golden);
  });

  it('the option present but undefined (what the server passes when the flag is off) changes nothing either', { timeout: 300_000 }, () => {
    expect(goldenRows(dir, { boundedExact: undefined })).toEqual(golden);
  });
});
